export interface Pr { user: { login: string }; body: string | null }
export interface Review { state: string; commit_id: string; user: { login: string; type: string } }

const AGENT_BOTS = new Set(["rhino-ai-agents[bot]"]);
const REQUESTED_BY = /^Requested-by:\s*@?([A-Za-z0-9-]+)\s*$/m;

export class MissingRequester extends Error {}

export function requesters(pr: Pr, commitAuthors: string[], bodyEditors: string[]): Set<string> {
  const people = [pr.user.login];
  if (AGENT_BOTS.has(pr.user.login)) {
    const m = REQUESTED_BY.exec(pr.body ?? "");
    if (!m) throw new MissingRequester("agent PR has no Requested-by line");
    people.push(m[1]);
  }
  return new Set([...people, ...commitAuthors, ...bodyEditors]);
}

export function independentApproval(
  reviews: Review[],
  headSha: string,
  excluded: Set<string>,
): string | undefined {
  const latest = new Map<string, Review>();
  for (const r of reviews) {
    if (r.user.type !== "User") continue;
    if (!["APPROVED", "CHANGES_REQUESTED", "DISMISSED"].includes(r.state)) continue;
    latest.set(r.user.login, r);
  }
  for (const [login, r] of latest) {
    if (excluded.has(login)) continue;
    if (r.state === "APPROVED" && r.commit_id === headSha) return login;
  }
  return undefined;
}
